const el=document.querySelector('#workspace'),status=document.querySelector('#status');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session=null,me=null,locale='en',busy=false,pendingImport=null;
const tr=(en,ar)=>locale==='ar'?ar:en;
const button=(text,action,id='')=>`<button class="btn" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',cache:'no-store',headers:data?{'Content-Type':'application/json','X-Companion-Local':'1','X-CSRF-Token':session?.csrf||''}:{},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok)throw new Error(result.error||'Request refused');return result;}
async function action(data){return api('/api/action',data);}
function notice(text){status.textContent=text;}
async function refresh(){
 document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';
 document.querySelector('#language').textContent=locale==='ar'?'English':'العربية';
 document.querySelector('#boundary').textContent=tr('Local synthetic workspace · Role-bound access · No external AI · Human-reviewed outcomes','مساحة محلية ببيانات اصطناعية · صلاحيات حسب الدور · دون ذكاء اصطناعي خارجي · مراجعة بشرية');
 try{session=await api('/api/session');}catch{session=null;}
 document.querySelector('#logout').hidden=!session;
 document.querySelector('#logout').textContent=tr('Sign out','تسجيل الخروج');
 if(!session){el.innerHTML=`<section class="card privacy-section"><h2>${tr('Sign in to your workspace','تسجيل الدخول إلى مساحة العمل')}</h2><p>${tr('Use your individually provisioned local account. Accounts bind an employee, named service owner, manager or administrator; there is no role selector.','استخدم حسابك المحلي المخصص. الحساب مرتبط بالموظف أو مالك الخدمة أو المدير أو المسؤول. لا يوجد محدد لتبديل الأدوار.')}</p><form id="login"><label class="modal-field"><span>${tr('Username','اسم المستخدم')}</span><input name="username" autocomplete="username" required></label><label class="modal-field"><span>${tr('Password','كلمة المرور')}</span><input name="password" type="password" autocomplete="current-password" required></label><button class="btn">${tr('Sign in','دخول')}</button></form><p class="muted">${tr('First visit? Run npm run setup from the repository, then use a login from local-data/login-credentials.txt. Start with employee-1 for onboarding or employee-2 for an internal move. No model installation is required.','للإعداد: استورد حزمة محلية ثم شغّل npm run accounts. بيانات الدخول محفوظة محلياً.')}</p></section>`;return;}
 const a=session.account;
 el.innerHTML=`<div class="section-header"><h2>${esc(a.name||a.username)} · ${esc(locale==='ar'?({employee:'موظف',owner:'مسؤول خدمة',manager:'مدير',admin:'مسؤول النظام'}[a.role]||a.role):a.role)}</h2>${button(tr('Refresh','تحديث'),'refresh')}</div>`;
 if(a.role==='employee'){
  me=await api('/api/me');const p=me.employee;const day=Math.max(1,Math.floor((new Date(p.asOf)-new Date(p.start))/86400000)+1),next=me.steps.find(s=>!s.complete&&!s.missing.length);const done=me.steps.filter(s=>s.complete).length;
  el.innerHTML+=`<section class="card privacy-section"><h2>${esc(p.name)}</h2><p>${esc(p.location)} · ${esc(p.journey)}</p><div class="journey-summary"><span>${tr("Journey day","يوم الرحلة")} ${day}</span><span>${done} / ${me.steps.length} ${tr("steps complete","خطوات مكتملة")}</span><span>${tr("Next:","التالي:")} ${esc(next?.title||tr("Journey complete","اكتملت الرحلة"))}</span></div><p>${tr('Only your journey is accessible. Feedback never goes to managers.','يمكنك الوصول إلى رحلتك فقط. لا تتم مشاركة الملاحظات مع المديرين.')}</p></section><section class="card privacy-section"><h2>${tr('Your journey and next steps','رحلتك والخطوات التالية')}</h2>${me.steps.map(s=>`<div class="task-row"><div class="task-text"><h3>${esc(s.title)}</h3><p>${esc(s.status)} · ${esc(s.owner.name)} · ${new Date(s.due).toLocaleDateString(locale==='ar'?'ar-AE':'en-GB')}</p></div>${!s.complete?button(tr('Review handoff','مراجعة الإحالة'),'handoff',s.id):''}</div>`).join('')}</section><section class="card privacy-section"><h2>${tr('Conversation','المحادثة')}</h2>${p.messages.map(m=>`<p><strong>${esc(m.role)}</strong>: ${esc(m.text)}${m.policy?` <button class="source-link" data-action="policy" data-id="${esc(m.policy)}">${esc(me.policies.find(x=>x.id===m.policy)?.code)} · ${esc(m.citationSection||'')}</button>`:''}</p>`).join('')}<form id="chat"><label class="modal-field"><span>${tr('Ask about your policies or next step','اسأل عن السياسات أو الخطوة التالية')}</span><input name="message" maxlength="1200" required></label><button class="btn">${tr('Ask companion','اسأل المرافق')}</button></form><p class="muted">${esc(session.ai.reason)}</p><p class="muted">${tr('Policy excerpts retain the source language; Arabic questions use a limited local vocabulary. Translation quality is not yet evaluated.','تُعرض المقتطفات بلغة المصدر. تدعم الأسئلة العربية مفردات محلية محدودة ولم تُقيّم جودة الترجمة بعد.')}</p></section><section class="card privacy-section"><h2>${tr('Requests and owner updates','الطلبات وتحديثات المسؤول')}</h2>${p.requests.map(r=>`<details><summary>${esc(r.title)} · ${esc(r.status)}</summary>${r.history.map(h=>`<p>${esc(h.text)}</p>`).join('')}</details>`).join('')||tr('No requests yet.','لا توجد طلبات بعد.')}</section><section class="card privacy-section"><h2>${tr('Your data and consent','بياناتك والموافقة')}</h2><p>${tr('Pulse sharing:','مشاركة الملاحظات:')} ${p.consent?tr('On','مفعّلة'):tr('Off','متوقفة')}</p>${button(p.consent?tr('Withdraw and delete feedback','سحب الموافقة وحذف الملاحظات'):tr('Opt in to check-ins','الموافقة على الملاحظات'),'consent') } ${button(tr('Export my records','تصدير سجلاتي'),'export')}${p.consent?`<form id="pulse"><label class="modal-field"><span>${tr('How is your journey?','كيف تسير رحلتك؟')}</span><select name="rating"><option value="good">${tr('Going well','تسير جيداً')}</option><option value="okay">${tr('Okay','مقبولة')}</option><option value="need-help">${tr('Could use support','أحتاج إلى دعم')}</option></select></label><label class="modal-field"><span>${tr('Optional comment','تعليق اختياري')}</span><textarea name="comment" maxlength="600"></textarea></label><button class="btn">${tr('Save check-in','حفظ الملاحظة')}</button></form>`:''}<p class="muted">${tr('Withdrawal deletes saved feedback, feedback attachments and conversations on the server. No manager sees these records. Questions are processed as typed.','سحب الموافقة يحذف الملاحظات والمرفقات والمحادثات المحفوظة على الخادم. لا يراها المديرون. تُعالج الأسئلة كما تكتبها.')}</p></section>`;
 }else if(a.role==='owner'){
  const {cases}=await api('/api/owner/cases');el.innerHTML+=`<h2>${tr('Your assigned cases','الحالات المسندة إليك')}</h2>${cases.map(c=>`<section class="card privacy-section"><h3>${esc(c.title)} · ${esc(c.employee)}</h3><p>${esc(c.status)}</p><p>${esc(c.summary)}</p><ul>${c.evidence.map(e=>`<li>${esc(e)}</li>`).join('')}</ul><p>${esc(c.message)}</p>${c.feedback.length?`<h3>${tr('Feedback explicitly shared by the employee','ملاحظات شاركها الموظف بموافقته')}</h3>${c.feedback.map(f=>`<p>${esc(f.comment)}</p>`).join('')}`:''}${c.status!=='Resolved'?`<form class="owner-update" data-id="${esc(c.id)}"><label class="modal-field"><span>${tr('Status','الحالة')}</span><select name="status"><option value="Acknowledged">${tr('Acknowledged','تم الاستلام')}</option><option value="Needs information">${tr('Needs information','معلومات إضافية')}</option><option value="Resolved">${tr('Resolved','تم الحل')}</option></select></label><label class="modal-field"><span>${tr('Outcome note (required)','ملاحظة النتيجة (مطلوبة)')}</span><textarea name="note" minlength="5" maxlength="1000" required></textarea></label><button class="btn">${tr('Record human decision','تسجيل القرار البشري')}</button></form>`:''}${(c.history||[]).map(h=>`<p>${esc(h.by)}: ${esc(h.note)}</p>`).join('')}</section>`).join('')||tr('No assigned cases.','لا توجد حالات مسندة.')}`;
 }else if(a.role==='manager'){
  const {joiners}=await api('/api/manager');el.innerHTML+=`<h2>${tr('Your new joiners','الموظفون الجدد في فريقك')}</h2><p>${tr('Milestones only. Conversations, pulse feedback and employee scores are excluded.','المراحل فقط. لا تُعرض المحادثات أو الملاحظات أو تقييمات الموظفين.')}</p>${joiners.map(p=>`<section class="card privacy-section"><h3>${esc(p.name)}</h3>${p.steps.map(s=>`<p>${esc(s.title)} · ${esc(s.status)} · ${esc(s.owner)}</p>`).join('')}</section>`).join('')||tr('No assigned new joiners.','لا يوجد موظفون جدد مسندون.')}`;
 }else if(a.role==='admin'){
  const data=await api('/api/stalls');el.innerHTML+=`<section class="card privacy-section"><h2>${tr('Where journeys stall','مواضع تعثر الرحلات')}</h2><p>${tr('Only groups of five or more are shown. No individual records or feedback are included.','تُعرض المجموعات التي تضم خمسة أشخاص أو أكثر فقط، دون سجلات فردية أو ملاحظات.')}</p>${data.groups.map(g=>`<p>${esc(g.step)}: ${g.count}</p>`).join('')||tr('No reportable groups.','لا توجد مجموعات قابلة للعرض.')}<p>${tr('Suppressed groups','المجموعات المحجوبة')}: ${data.suppressedGroups}</p></section><section class="card privacy-section"><h2>${tr('Import a synthetic pack','استيراد حزمة اصطناعية')}</h2><form id="import-pack"><label class="modal-field"><span>${tr('Pack folder','مجلد الحزمة')}</span><input type="file" id="import-files" webkitdirectory multiple required></label><label><input type="checkbox" name="synthetic" required>${tr('Synthetic data only','بيانات اصطناعية فقط')}</label><button class="btn">${tr('Validate locally','التحقق محلياً')}</button></form><div id="import-report"></div></section>`;
 }
}
document.querySelector('#language').onclick=()=>{locale=locale==='en'?'ar':'en';refresh().catch(e=>notice(e.message));};
document.querySelector('#logout').onclick=async()=>{await action({action:'logout'});session=null;me=null;await refresh();};
document.addEventListener('submit',async e=>{
 e.preventDefault();if(busy)return;busy=true;const data=Object.fromEntries(new FormData(e.target));
 try{notice(tr('Working locally…','جارٍ التنفيذ محلياً…'));
 if(e.target.id==='import-pack'){const files=Object.create(null),list=[...document.querySelector('#import-files').files];if(list.length>1000||list.reduce((n,f)=>n+f.size,0)>20*1024*1024)throw new Error('Pack limit exceeded');for(const f of list)files[f.webkitRelativePath||f.name]=await f.text();pendingImport={files,syntheticOnly:true};const {report}=await api('/api/pack/validate',pendingImport);document.querySelector('#import-report').innerHTML=`<pre style="white-space:pre-wrap">${esc(JSON.stringify(report,null,2))}</pre>${report.ok?button(tr('Replace active pack','استبدال الحزمة الحالية'),'import-apply'):''}`;notice('Validation complete');return;}
 if(e.target.id==='login')await api('/api/session',data);
 else if(e.target.id==='chat')await action({action:'chat',message:data.message});
 else if(e.target.id==='pulse')await action({action:'pulse',...data});
 else if(e.target.classList.contains('owner-update'))await action({action:'ownerUpdate',caseId:e.target.dataset.id,...data});
 await refresh();notice(tr('Saved locally.','تم الحفظ محلياً.'));
 }catch(err){notice(err.message);}finally{busy=false;}
});
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||busy)return;const type=b.dataset.action,id=b.dataset.id;
 try{
 if(type==='import-apply'){busy=true;await api('/api/pack/import',pendingImport);pendingImport=null;await refresh();notice(tr('Pack loaded. Reprovision role-bound accounts if employee or owner assignments changed.','تم تحميل الحزمة. حدّث الحسابات إذا تغيرت تعيينات الموظفين أو المسؤولين.'));return;}
 if(type==='refresh'){await refresh();return;}
 if(type==='policy'){const p=me.policies.find(x=>x.id===id);const section=document.createElement('section');section.className='card privacy-section';section.innerHTML=`<h2>${esc(p.title)}</h2><p>${esc(p.source)} · ${esc(p.version)}</p>${p.paragraphs.map(t=>`<p>${esc(t)}</p>`).join('')}`;el.append(section);section.scrollIntoView();return;}
 if(type==='handoff'){
  const step=me.steps.find(s=>s.id===id);el.innerHTML+=`<section class="card privacy-section" id="handoff-review"><h2>${tr('Review before sharing','مراجعة قبل المشاركة')}</h2><p>${esc(step.title)} → ${esc(step.owner.name)}</p><p>${tr('Includes your name, journey evidence and relevant request. The named owner will receive this case locally.','تتضمن الإحالة اسمك وأدلة الرحلة والطلب المعني. سيتلقى المسؤول المحدد هذه الحالة محلياً.')}</p><label class="modal-field"><span>${tr('Optional note','ملاحظة اختيارية')}</span><textarea id="handoff-note" maxlength="1000"></textarea></label>${me.employee.consent&&me.employee.pulses.length?`<label><input type="checkbox" id="share-pulse">${tr('Include my saved feedback (optional)','تضمين ملاحظاتي المحفوظة (اختياري)')}</label>`:''}${button(tr('Submit to named owner','إرسال إلى المسؤول المحدد'),'submit-handoff',id)}</section>`;document.querySelector('#handoff-review').scrollIntoView();return;
 }
 busy=true;
 if(type==='submit-handoff')await action({action:'handoff',taskId:id,note:document.querySelector('#handoff-note').value,includePulse:!!document.querySelector('#share-pulse')?.checked});
 if(type==='consent')await action({action:'consent',allowed:!me.employee.consent});
 if(type==='export'){const {result}=await action({action:'export'});const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='my-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 await refresh();notice(tr('Saved locally.','تم الحفظ محلياً.'));
 }catch(err){notice(err.message);}finally{busy=false;}
});
refresh().catch(e=>notice(e.message));
